/** A command's icon, or null: a command without one is a named menu entry. */
fun commandIcon(id: String): ImageVector? = when (id) {
    "file.new" -> Lucide.FilePlus
    "file.open" -> Lucide.FolderOpen
    "file.save" -> Lucide.Save
    "edit.undo" -> Lucide.Undo2
    "edit.redo" -> Lucide.Redo2
    "layer.new" -> Lucide.SquarePlus
    "layer.delete" -> Lucide.Trash2
    "ease.save" -> Lucide.Save
    "ease.delete" -> Lucide.Trash2
    "ease.copy" -> Lucide.Copy
    "ease.paste" -> Lucide.ClipboardPaste
    "scene.duplicate" -> Lucide.CopyPlus
    "scene.delete" -> Lucide.Trash2
    "frames.delete" -> Lucide.Trash2
    "frames.copy" -> Lucide.Copy
    "frames.cut" -> Lucide.Scissors
    "frames.paste" -> Lucide.ClipboardPaste
    "edit.delete" -> Lucide.Trash2
    "edit.duplicate" -> Lucide.CopyPlus
    "modify.group" -> Lucide.Group
    "modify.ungroup" -> Lucide.Ungroup
    "modify.crop" -> Lucide.Crop
    "library.duplicate" -> Lucide.CopyPlus
    "library.delete" -> Lucide.Trash2
    "edit.cut" -> Lucide.Scissors
    "edit.copy" -> Lucide.Copy
    "edit.paste" -> Lucide.ClipboardPaste
    "find.replace" -> Lucide.Replace
    "filter.copy" -> Lucide.Copy
    "filter.paste" -> Lucide.ClipboardPaste
    "swatch.duplicate" -> Lucide.CopyPlus
    "sound.delete" -> Lucide.Trash2
    else -> null
}

/** A tool's icon by its id in [TOOLS], or null. */
fun toolIcon(id: String): ImageVector? = when (id) {
    "Select" -> Lucide.MousePointer2
    "Subselect" -> Lucide.MousePointer2
    "GradientTransform" -> Lucide.Blend
    "Pen" -> Lucide.PenTool
    "Text" -> Lucide.Type
    "Pencil" -> Lucide.Pencil
    "Brush" -> Lucide.Brush
    "PaintBrush" -> Lucide.Brush
    "Eraser" -> Lucide.Eraser
    "Rect" -> Lucide.Square
    "Oval" -> Lucide.Circle
    "Star" -> Lucide.Star
    "Line" -> Lucide.Minus
    "PaintBucket" -> Lucide.PaintBucket
    "InkBottle" -> Lucide.PenLine
    "Eyedropper" -> Lucide.Pipette
    "Hand" -> Lucide.Hand
    "Zoom" -> Lucide.ZoomIn
    else -> null
}

